<section class="page-hero"><div class="container"><span class="eyebrow"><?= $this->escape($product['category_name'] ?: 'Digital Product') ?></span><h1><?= $this->escape($product['name']) ?></h1></div></section>
<section class="content-section"><div class="container contact-layout"><div class="product-detail-image"><?php $productImage = $this->imageUrl($product['thumbnail'] ?? ''); if ($productImage !== ''): ?><img src="<?= $this->escape($productImage) ?>" alt="<?= $this->escape($product['name']) ?>"><?php else: ?><span><?= $this->escape(substr($product['name'],0,1)) ?></span><?php endif ?></div><div><h2><?= $this->escape($product['short_description'] ?: 'Digital product') ?></h2><p><?= nl2br($this->escape($product['description'] ?: 'Detailed product information is provided at checkout.')) ?></p><h3><?= $this->escape($product['currency']) ?> <?= number_format((float)$product['price'],2) ?></h3>
<?php if ($product['fulfillment_mode'] === 'external_vendor' && $product['checkout_url']): ?><a class="button" target="_blank" rel="noopener noreferrer" href="<?= $this->escape($product['checkout_url']) ?>">Buy from vendor <i data-lucide="external-link"></i></a>
<?php elseif ($product['fulfillment_mode'] === 'inquiry_required'): ?><a class="button" href="<?= $this->escape(appUrl('/contact')) ?>">Request quotation</a>
<?php else:?><a class="button" href="<?= $this->escape(appUrl('/checkout')) ?>">Continue to checkout</a><?php endif ?>
</div></div></section>
